public final class Download {
    public let id: Int
    public private(set) var progress = 0
    public init(id: Int) { self.id = id }
    public func advance(to value: Int) {
        guard value >= progress && value <= 100 else { return }
        progress = value
    }
}

public у класса не открывает его члены: id, чтение progress, init и advance помечены отдельно. public private(set) — читать снаружи можно, писать только внутри. open не нужен: он разрешил бы наследование и переопределение из другого модуля, а нам это запрещено; final оставляем — он запрещает наследование и внутри модуля.

