final class Download {
    let id = 40
    private(set) var isPaused = false
    func pause() { isPaused = true }
    func resume() { isPaused = false }
}
let download = Download()
download.pause()
print(download.isPaused)
download.resume()
print(download.isPaused)

Снаружи нельзя подменить флаг присваиванием; команды меняют его внутри Download. Вывод true и false.

final class Download {
    let id = 40
    let totalBytes = 50
    private(set) var downloadedBytes = 0
    func add(bytes: Int) {
        guard bytes > 0 && bytes <= totalBytes - downloadedBytes else { return }
        downloadedBytes += bytes
    }
}
let download = Download()
download.add(bytes: 20)
download.add(bytes: 40)
download.add(bytes: -1)
download.add(bytes: 0)
download.add(bytes: 30)
print(download.downloadedBytes)

20 принято, 40 отвергнуто, отрицательный и нулевой куски отвергнуты, 30 завершает объём 50. Доступ и проверка величины защищают разные части контракта.
